def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    # Assume a Point has x and y attributes
    return {'x': getattr(value, 'x', None), 'y': getattr(value, 'y', None)}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(super().keys())

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Assume the class has a mapping of supported handlers
        # keyed by version tuples, e.g. cls._protocol_handlers.
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            if protocol_version in getattr(cls, "_protocol_handlers", {}):
                return {protocol_version: cls._protocol_handlers[protocol_version]}
            return {}
        # Return a copy of all available handlers
        return dict(getattr(cls, "_protocol_handlers", {}))

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no filtering keys are provided, return all values
    if not keys:
        # Assume the object behaves like a mapping
        try:
            return list(self.values())
        except AttributeError:
            # Fallback: try to use items() and extract values
            try:
                return [v for _, v in self.items()]
            except AttributeError:
                # As a last resort, use the object's __dict__
                return list(self.__dict__.values())

    # Prepare a list to hold the filtered values
    result = []

    # Convert the mapping to a list of values for index-based access
    try:
        all_values = list(self.values())
    except AttributeError:
        try:
            all_values = [v for _, v in self.items()]
        except AttributeError:
            all_values = list(self.__dict__.values())

    for key in keys:
        if isinstance(key, int):
            # Index-based access
            if 0 <= key < len(all_values):
                result.append(all_values[key])
            else:
                raise IndexError(f"Index {key} out of range for values list")
        elif isinstance(key, str):
            # Key-based access
            if hasattr(self, key):
                result.append(getattr(self, key))
            elif isinstance(self, dict) and key in self:
                result.append(self[key])
            else:
                # Try to find the key in the mapping
                try:
                    result.append(self[key])
                except (KeyError, TypeError):
                    raise KeyError(f"Key '{key}' not found in the record")
        else:
            raise TypeError(f"Unsupported key type: {type(key).__name__}")

    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine the underlying data structure
    if hasattr(self, "_data"):
        data = self._data
    elif hasattr(self, "data"):
        data = self.data
    else:
        # Fallback: use public attributes as key-value pairs
        data = {k: v for k, v in self.__dict__.items() if not k.startswith("_")}

    # If no keys specified, return all items
    if not keys:
        return dict(data)

    result = {}
    # Convert data to a list of items for index access
    items = list(data.items())
    for key in keys:
        if isinstance(key, int):
            # Index-based access
            if key < 0 or key >= len(items):
                raise IndexError(f"Index {key} out of bounds")
            k, v = items[key]
            result[k] = v
        else:
            # Key-based access
            result[key] = data.get(key, None)
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    class_dict = dict(fields)
    class_dict['srid_map'] = srid_map
    return type(name, (Point,), class_dict)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__} is deprecated: {message}",
                          DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    s = s.strip()
    if not s:
        return ()
    parts = s.split('.')
    nums = []
    for part in parts:
        # try to parse the whole part as an integer
        try:
            nums.append(int(part))
            continue
        except ValueError:
            pass
        # if the part contains non-digit characters, extract the leading digits
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            nums.append(int(num_str))
        else:
            # if no digits found, treat as 0
            nums.append(0)
    return tuple(nums)

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorating_function(user_function):
        cache = {}
        hits = misses = 0
        maxsize_local = maxsize

        def make_key(args, kwds, typed):
            key = args
            if kwds:
                key += tuple(sorted(kwds.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwds:
                    key += tuple(type(v) for k, v in sorted(kwds.items()))
            return key

        def wrapper(*args, **kwds):
            nonlocal hits, misses
            key = make_key(args, kwds, typed)
            if key in cache:
                hits += 1
                result = cache.pop(key)
                cache[key] = result
                return result
            misses += 1
            result = user_function(*args, **kwds)
            cache[key] = result
            if maxsize_local is not None and len(cache) > maxsize_local:
                cache.pop(next(iter(cache)))
            return result

        def cache_info():
            return hits, misses, maxsize_local, len(cache)

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper
    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorating_function(user_function):
        cache = {}
        hits = misses = 0

        def make_key(args, kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = make_key(args, kwargs)
            if key in cache:
                value, count = cache[key]
                cache[key] = (value, count + 1)
                hits += 1
                return value
            result = user_function(*args, **kwargs)
            if len(cache) >= maxsize:
                # evict least frequently used item
                evict_key = None
                min_count = None
                for k, (_, c) in cache.items():
                    if min_count is None or c < min_count:
                        min_count = c
                        evict_key = k
                if evict_key is not None:
                    del cache[evict_key]
            cache[key] = (result, 1)
            misses += 1
            return result

        wrapper.cache_info = lambda: (hits, misses, len(cache), maxsize)
        return wrapper

    return decorating_function

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    if key not in self:
        self[key] = default
    return self[key]

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

@staticmethod
def is_file_exist(file_name):
    """Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        with open(file_name, 'rb'):
            return True
    except (FileNotFoundError, OSError):
        return False

def _getTargetClass(self):
    """Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix."""
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    cls = self.__class__
    if all:
        # include attributes from the class and all base classes
        for base in cls.__mro__:
            for name, obj in base.__dict__.items():
                if name.startswith('_'):
                    continue
                if isinstance(obj, property):
                    desc = obj.__doc__
                    if desc:
                        result[name] = desc
                elif hasattr(obj, '__doc__'):
                    desc = obj.__doc__
                    if desc:
                        result[name] = desc
    else:
        # only attributes defined directly on this class
        for name, obj in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if isinstance(obj, property):
                desc = obj.__doc__
                if desc:
                    result[name] = desc
            elif hasattr(obj, '__doc__'):
                desc = obj.__doc__
                if desc:
                    result[name] = desc
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Class-level attributes (excluding methods and private names)
    class_attrs = {
        name
        for name, value in vars(self.__class__).items()
        if not callable(value) and not name.startswith("_")
    }

    if all:
        # Instance-level attributes (excluding methods and private names)
        instance_attrs = {
            name
            for name, value in vars(self).items()
            if not callable(value) and not name.startswith("_")
        }
        return sorted(class_attrs | instance_attrs)

    return sorted(class_attrs)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        # Expand tuples or lists into individual elements
        if isinstance(arg, (list, tuple)):
            output.extend(arg)
        else:
            output.append(arg)
    return output

def _c_optimizations_ignored(self):
    """The opposite of `_c_optimizations_required`."""
    return not self._c_optimizations_required()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if getattr(self, 'initial_value', None) is not None:
        for key in self.bins:
            self.bins[key] = self.initial_value
    else:
        self.bins = self.make_bins()

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, Source):
        return False
    if isinstance(seq, FillRequest):
        return True
    try:
        for e in seq:
            if isinstance(e, FillRequest):
                return True
    except TypeError:
        return False
    return False

