def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        return None
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            if first_level and key == 'metadata':
                result[key] = value
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = value
        else:
            if first_level and key in ('apiVersion', 'kind'):
                result[key] = value
            else:
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    def _update_dict(last, schema, resp):
        for key in schema:
            if isinstance(key, dict):
                for k, sub_schema in key.items():
                    if k not in last:
                        last[k] = {}
                    if k not in resp:
                        continue
                    if isinstance(sub_schema, list):
                        if not isinstance(last[k], list):
                            last[k] = []
                        for idx, item_schema in enumerate(sub_schema):
                            if idx >= len(last[k]):
                                last[k].append({})
                            if isinstance(item_schema, dict):
                                _update_dict(last[k][idx], item_schema, resp[k][idx])
                    else:
                        if not isinstance(last[k], dict):
                            last[k] = {}
                        _update_dict(last[k], sub_schema, resp[k])
            else:
                if key not in last and key in resp:
                    last[key] = resp[key]

    _update_dict(last_applied_manifest, observer_schema, response)

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in response")
        # If the key is not yet in last_applied_manifest, initialize it
        if key not in last_applied_manifest:
            if isinstance(sub_schema, dict):
                last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            elif isinstance(sub_schema, list):
                last_applied_manifest[key] = []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            else:
                # Primitive value
                last_applied_manifest[key] = response[key]
        else:
            # Key already exists; update nested structures if necessary
            if isinstance(sub_schema, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            elif isinstance(sub_schema, list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os

    # Resolve the root directory
    if hasattr(path, "root"):
        root = path.root
    else:
        root = path

    # The root must be a directory
    if not os.path.isdir(root):
        return False

    # Check for the mandatory .ocfl_version file
    version_file = os.path.join(root, ".ocfl_version")
    if not os.path.isfile(version_file):
        return False

    # Check for the mandatory objects directory
    objects_dir = os.path.join(root, "objects")
    if not os.path.isdir(objects_dir):
        return False

    # Ensure there is at least one object directory inside objects/
    try:
        has_object = any(
            os.path.isdir(os.path.join(objects_dir, d))
            for d in os.listdir(objects_dir)
        )
    except OSError:
        return False

    if not has_object:
        return False

    # Basic sanity checks passed
    return True

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        return prefix + 'No status'
    if isinstance(status, dict):
        parts = [f'{k}={v}' for k, v in status.items()]
        return prefix + '; '.join(parts)
    if isinstance(status, (list, tuple)):
        return prefix + '; '.join(str(s) for s in status)
    return prefix + str(status)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # If the object does not have a validation log, return an empty string
    if not hasattr(self, 'validation_log'):
        return ''
    # Convert each log entry to a string, prefixing it if requested
    return "\n".join(f"{prefix}{str(entry)}" for entry in self.validation_log)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a mapping
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict-like object")

    # Extract spec version if requested
    if extract_spec_version:
        inv_type = inventory.get('type')
        if isinstance(inv_type, str) and inv_type in ('1.0', '2.0', '3.0'):
            self.spec_version = inv_type
        else:
            # keep existing spec_version
            pass

    # Basic required fields
    required_keys = ['id', 'name']
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key '{key}' in inventory")

    # Version‑specific validation
    if self.spec_version == '1.0':
        # For spec 1.0, inventory must contain an 'items' list
        if 'items' not in inventory or not isinstance(inventory['items'], list):
            raise ValueError("Inventory for spec 1.0 must contain an 'items' list")
    elif self.spec_version == '2.0':
        # For spec 2.0, inventory must contain an 'entries' dict
        if 'entries' not in inventory or not isinstance(inventory['entries'], dict):
            raise ValueError("Inventory for spec 2.0 must contain an 'entries' dict")
    else:
        # Unsupported or unknown spec version
        raise ValueError(f"Unsupported spec version: {self.spec_version}")

    # If all checks pass, return True
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    manifest_digests = set(manifest_files.keys())
    missing = digests_used - manifest_digests
    if missing:
        raise ValueError(f"Digests used but not present in manifest: {', '.join(sorted(missing))}")
    unused = manifest_digests - digests_used
    if unused:
        raise ValueError(f"Digests present in manifest but not used: {', '.join(sorted(unused))}")
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an InventoryValidator instance
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Ensure both inventories have the same identifier
    if getattr(self, "inventory_id", None) != getattr(prior, "inventory_id", None):
        raise ValueError("Inventory IDs do not match between current and prior inventories")

    # Ensure both inventories have a version attribute
    if getattr(self, "version", None) is None or getattr(prior, "version", None) is None:
        raise ValueError("Both inventories must have a 'version' attribute")

    # Prior must be older than the current inventory
    if prior.version >= self.version:
        raise ValueError("Prior inventory must have a lower version number than the current inventory")

    # Ensure all items in the prior inventory exist in the current inventory
    # (Assuming items are stored in a dict keyed by an identifier)
    if hasattr(prior, "items") and hasattr(self, "items"):
        for key, item in prior.items.items():
            if key not in self.items:
                raise ValueError(f"Item '{key}' present in prior inventory but missing in current inventory")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}

    # Handle inventory as a mapping from version to {logical_path: content_file}
    if isinstance(inventory, dict):
        for ver, mapping in inventory.items():
            # Skip earlier versions
            try:
                if ver < version:
                    continue
            except Exception:
                # If comparison fails, skip this entry
                continue

            if isinstance(mapping, dict):
                for lp, cf in mapping.items():
                    result.setdefault(lp, set()).add(cf)
            else:
                # If mapping is not a dict, try to iterate over it as (lp, cf) pairs
                for item in mapping:
                    if isinstance(item, (list, tuple)) and len(item) == 2:
                        lp, cf = item
                        result.setdefault(lp, set()).add(cf)

    # Handle inventory as a list of entries with 'version', 'logical_path', 'content_file'
    elif isinstance(inventory, list):
        for entry in inventory:
            if not isinstance(entry, dict):
                continue
            entry_version = entry.get('version')
            try:
                if entry_version < version:
                    continue
            except Exception:
                continue

            lp = entry.get('logical_path')
            cf = entry.get('content_file')
            if lp is None or cf is None:
                continue
            result.setdefault(lp, set()).add(cf)

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dict")
    if 'files' not in fixity:
        raise ValueError("fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise TypeError("'files' must be a list")

    # Ensure manifest_files is a set for fast lookup
    manifest_set = set(manifest_files)

    for entry in files:
        if not isinstance(entry, dict):
            raise TypeError("each file entry must be a dict")
        if 'path' not in entry:
            raise ValueError("file entry missing 'path'")
        path = entry['path']
        if path not in manifest_set:
            raise ValueError(f"file '{path}' referenced in fixity not present in manifest")
        if 'checksum' not in entry:
            raise ValueError(f"file '{path}' missing checksum")

    return True

def files_list(path):
    """Return the files in `path`"""
    import os
    if not os.path.isdir(path):
        raise ValueError(f"Path {path!r} is not a directory")
    return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]

