def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * indent
    parts = [f"{indent_str}{self.__class__.__name__}("]
    attrs = []
    for key, value in self.__dict__.items():
        if key.startswith('_'):
            continue
        if isinstance(value, list):
            items = []
            for item in value:
                if hasattr(item, 'pretty'):
                    items.append(item.pretty(indent + 2, debug))
                else:
                    items.append(repr(item))
            attrs.append(f"{key}=[{', '.join(items)}]")
        else:
            if hasattr(value, 'pretty'):
                attrs.append(f"{key}={value.pretty(indent + 2, debug)}")
            else:
                attrs.append(f"{key}={repr(value)}")
    parts.append(', '.join(attrs))
    parts.append(")")
    return ''.join(parts)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            if isinstance(result, unicode):
                return result.encode('utf-8')
            return result
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+
        from importlib.metadata import version, PackageNotFoundError
    except ImportError:
        try:
            # Backport for older Python
            from importlib_metadata import version, PackageNotFoundError
        except ImportError:
            # importlib.metadata not available
            return {"version": "0.0.0", "error": "importlib.metadata not available"}

    # Determine the package name from the current module
    pkg = __package__ or __name__
    pkg_name = pkg.split('.')[0] if pkg else None

    if not pkg_name:
        return {"version": "0.0.0", "error": "Unable to determine package name"}

    try:
        ver = version(pkg_name)
        return {"version": ver}
    except PackageNotFoundError:
        return {"version": "0.0.0", "error": f"Package {pkg_name} not found"}
    except Exception as exc:
        return {"version": "0.0.0", "error": str(exc)}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    rendered = []
    for piece in pieces:
        if hasattr(piece, 'render'):
            rendered.append(piece.render(style))
        else:
            rendered.append(str(piece))
    return ''.join(rendered)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '.' if '+' in pieces else '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    results = []
    for cmd in commands:
        # Build the command list
        if isinstance(cmd, (list, tuple)):
            cmd_list = list(cmd)
        else:
            cmd_list = [cmd] + list(args)
        if verbose:
            print(f"Running command: {' '.join(cmd_list)}")
        stderr = subprocess.DEVNULL if hide_stderr else None
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True
        )
        results.append(result)
    return results

