def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Iterate over all objects in the hierarchy (including the root itself)
    for obj in self:
        num_objects += 1
        valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                # Assume the object has a validate() method that returns a bool
                valid = obj.validate()
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"Validation error in {obj!r}: {exc}")

        # Check the digest if requested and the object passed validation
        if check_digests and valid:
            try:
                # Assume the object has a check_digest() method that returns a bool
                if not obj.check_digest():
                    valid = False
                    if show_warnings:
                        print(f"Digest mismatch in {obj!r}")
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"Digest check error in {obj!r}: {exc}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

