def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    mu = 0.2
    sigma = 0.1
    return np.exp(-((x - mu)**2) / (2 * sigma**2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_dict = {}
    error_records = []
    logger = logging.getLogger(__name__)
    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                content = f.read()
            if resolve_env:
                import re, os
                content = re.sub(r'\$\{([^}]+)\}', lambda m: os.getenv(m.group(1), ''), content)
            try:
                import json
                config = json.loads(content)
            except Exception:
                try:
                    import yaml
                    config = yaml.safe_load(content)
                except Exception as e:
                    record = logging.LogRecord(logger.name, logging.ERROR, filename, 0,
                                               f"Failed to parse configuration file {filename}: {e}", (), None)
                    error_records.append(record)
                    continue
            if overrides:
                if isinstance(overrides, dict):
                    config.update(overrides)
                else:
                    record = logging.LogRecord(logger.name, logging.ERROR, filename, 0,
                                               f"Overrides must be a dict, got {type(overrides)}", (), None)
                    error_records.append(record)
                    continue
            config_dict[filename] = config
        except FileNotFoundError:
            record = logging.LogRecord(logger.name, logging.ERROR, filename, 0,
                                       f"Configuration file not found: {filename}", (), None)
            error_records.append(record)
        except Exception as e:
            record = logging.LogRecord(logger.name, logging.ERROR, filename, 0,
                                       f"Error loading configuration file {filename}: {e}", (), None)
            error_records.append(record)
    return config_dict, error_records

def force_string(obj):
