@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        return {protocol_version: cls._protocol_handlers[protocol_version]} if protocol_version in cls._protocol_handlers else {}
    return dict(cls._protocol_handlers)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type, return it
    if isinstance(seq, (list, tuple, set, frozenset, str, bytes)):
        return seq, type(seq)
    # If seq is a file-like object, read its content
    if hasattr(seq, 'read'):
        if bufsize is not None:
            data = seq.read(bufsize)
        else:
            data = seq.read()
        # If data is a string or bytes, return it
        if isinstance(data, (str, bytes)):
            return data, type(data)
        # Otherwise, try to convert to list
        try:
            seq = list(data)
        except TypeError:
            seq = [data]
        return seq, type(seq)
    # If seq is an iterator or generator, convert to list
    try:
        seq = list(seq)
    except TypeError:
        seq = [seq]
    return seq, type(seq)

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Determine the object to inspect (class or instance)
    target = candidate if isinstance(candidate, type) else candidate

    # If candidate is a subclass of the interface, it's automatically valid
    if isinstance(candidate, type) and issubclass(candidate, iface):
        return True

    # Iterate over all public attributes of the interface
    for attr in dir(iface):
        if attr.startswith('_'):
            continue  # skip private and special attributes
        if not hasattr(target, attr):
            if tentative:
                # In tentative mode, missing attributes are ignored
                continue
            raise TypeError(
                f"Candidate {candidate!r} does not provide required attribute "
                f"'{attr}' for interface {iface.__name__}"
            )
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    # Determine the most derived metaclass from the bases
    metaclasses = [type(b) for b in bases]
    most_derived = metaclasses[0]
    for m in metaclasses[1:]:
        if issubclass(m, most_derived):
            most_derived = m
        elif not issubclass(most_derived, m):
            raise TypeError(
                f"metaclass conflict: {m.__name__} is not a subclass of {most_derived.__name__}"
            )
    return most_derived

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem from an empty container')
    # Try to use a frequency map if the object keeps one
    freq_map = getattr(self, '_freq', None) or getattr(self, 'freq', None)
    if freq_map:
        # Find the key with the lowest frequency
        min_key = min(freq_map, key=freq_map.get)
        value = self.pop(min_key)
        # Remove the key from the frequency map
        freq_map.pop(min_key, None)
        # If there is a structure that groups keys by frequency, update it
        freq_items = getattr(self, '_freq_items', None)
        if freq_items:
            # The frequency of the removed key is the one we just used
            freq = freq_map.get(min_key, None)
            if freq is not None:
                freq_items.get(freq, {}).pop(min_key, None)
                if not freq_items.get(freq):
                    freq_items.pop(freq, None)
        # Update the minimum frequency if needed
        if freq_items:
            if freq_items:
                self._min_freq = min(freq_items)
            else:
                self._min_freq = None
        return (min_key, value)
    else:
        # Fallback to the default dictionary popitem if no frequency tracking
        return super().popitem()

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    return self.popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    return self._data.popitem(last=True)

