def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    # Common ways to identify a Matrix request:
    # 1. The request type or action is 'matrix'
    # 2. The request contains a 'matrix' key in its payload
    # 3. The request path or URL contains '/matrix'
    try:
        # Check for explicit type attribute
        if getattr(request, 'type', None) == 'matrix':
            return True
        # Check for matrix key in payload
        if hasattr(request, 'payload') and isinstance(request.payload, dict):
            if 'matrix' in request.payload:
                return True
        # Check for matrix in URL
        if hasattr(request, 'url') and '/matrix' in request.url:
            return True
        # Fallback: check for matrix in headers
        if hasattr(request, 'headers') and isinstance(request.headers, dict):
            if any('matrix' in key.lower() for key in request.headers):
                return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Use ISO 8601 format with optional timezone offset
    if dt.tzinfo is None:
        return dt.strftime("%Y-%m-%dT%H:%M:%S")
    else:
        offset = dt.strftime("%z")
        if offset == "+0000":
            offset = "Z"
        return dt.strftime("%Y-%m-%dT%H:%M:%S") + offset

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        # Perform a HEAD request to get headers without downloading the body
        response = requests.head(url, allow_redirects=True, timeout=10)
        # Only consider successful responses
        if response.status_code == 200:
            return response.headers.get('Content-Type')
    except Exception:
        # Any error (network, timeout, etc.) results in None
        pass
    return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str) or not tag:
        return False
    # Tag must start with a letter
    if not tag[0].isalpha():
        return False
    # Allowed characters: letters, digits, hyphen, underscore
    for ch in tag:
        if not (ch.isalnum() or ch in ('-', '_')):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children_dict = {}
    for child in node:
        tag = child.tag
        if tag in children_dict:
            # If we already have an entry for this tag, store a list of children
            if isinstance(children_dict[tag], list):
                children_dict[tag].append(child)
            else:
                children_dict[tag] = [children_dict[tag], child]
        else:
            children_dict[tag] = child
    return children_dict

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Default to the standard NodeInfo 1.0 document path if none provided
    if document_path is None:
        document_path = "/.well-known/nodeinfo/1.0"
    # Ensure the document path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path
    # Build the full href, stripping any trailing slash from the base URL
    href = url.rstrip("/") + document_path
    # Return the minimal .well-known document structure
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        result: Dict = {}
        result["subject"] = data.get("subject")
        links = data.get("links", [])
        result["links"] = []
        for link in links:
            if isinstance(link, dict):
                result["links"].append(link)
        return result
    except json.JSONDecodeError:
        pass  # fall back to XRD

    # Try XRD (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError("Invalid webfinger document format") from exc

    # Namespace handling
    ns = {"xrd": "http://xrd.info/schema/1.0"}
    subject_elem = root.find("Subject") or root.find("xrd:Subject", ns)
    subject = subject_elem.text if subject_elem is not None else None

    links: list[Dict] = []
    for link_elem in root.findall("Link") + root.findall("xrd:Link", ns):
        link: Dict = {}
        for attr in ("rel", "href", "type", "template"):
            if attr in link_elem.attrib:
                link[attr] = link_elem.attrib[attr]
        links.append(link)

    return {"subject": subject, "links": links}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    import urllib.request
    # Normalize handle
    if handle.startswith("acct:"):
        resource = handle[5:]
    else:
        resource = handle
    if '@' not in resource:
        return None
    local, domain = resource.split('@', 1)
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{resource}"
    try:
        with urllib.request.urlopen(url, timeout=5) as resp:
            data = resp.read()
            return data.decode('utf-8')
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if '@' not in handle:
        raise ValueError("Handle must be in the form user@domain")
    user, domain = handle.split('@', 1)
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    except Exception as e:
        raise RuntimeError(f"Failed to retrieve webfinger for {handle}: {e}") from e
    try:
        data = resp.json()
    except Exception as e:
        raise ValueError(f"Failed to parse JSON from webfinger response for {handle}: {e}") from e
    return data

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error

    url = f"https://{host}/.well-known/host-meta"
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            data = resp.read()
    except urllib.error.HTTPError as e:
        raise ValueError(f"Failed to retrieve host-meta from {host}: HTTP {e.code}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"Failed to retrieve host-meta from {host}: {e}") from e

    try:
        return XRD.fromstring(data)
    except Exception as e:
        raise ValueError(f"Failed to parse host-meta from {host}: {e}") from e

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    file_names = []
    for dir_path in settings_dirs:
        if not os.path.isdir(dir_path):
            continue
        for entry in os.listdir(dir_path):
            full_path = os.path.join(dir_path, entry)
            if os.path.isfile(full_path):
                if spec_option is None or entry.endswith(spec_option):
                    file_names.append(full_path)
    return file_names

@classmethod
def workspace_manager(cls):
    """Gets the workspace manager. """
    return cls._workspace_manager

@classmethod
def plugins_manager(cls):
    """Gets the plugin manager. """
    return cls._plugins_manager

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    for name, spec in parser_dict.items():
        if not isinstance(spec, dict):
            raise TypeError(f"Group spec for '{name}' must be a dict, got {type(spec).__name__}")

        # Resolve nested includes
        if "include" in spec:
            nested = spec.pop("include")
            if isinstance(nested, dict):
                self._include_groups(nested)
            else:
                raise TypeError(f"Nested include for group '{name}' must be a dict")

        # Merge or add the group definition
        if hasattr(self, "groups") and name in self.groups:
            # Merge dictionaries – later definitions override earlier ones
            self.groups[name].update(spec)
        else:
            # Ensure the groups container exists
            if not hasattr(self, "groups"):
                self.groups = {}
            self.groups[name] = spec

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    spec = getattr(self, 'spec', {})
    for name in getattr(self, 'args', {}):
        defaults[name] = spec.get(name, None)
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Assume self.deprecated_args is a dict mapping deprecated argument names
        # to a deprecation message or a tuple of (message, replacement).
        if not hasattr(self, 'deprecated_args'):
            return

        def _warn(arg_name, source):
            info = self.deprecated_args.get(arg_name)
            if isinstance(info, tuple):
                msg, replacement = info
                print(f"WARNING: Argument '{arg_name}' from {source} is deprecated: {msg}. "
                      f"Use '{replacement}' instead.")
            else:
                print(f"WARNING: Argument '{arg_name}' from {source} is deprecated: {info}")

        for arg in cli_args:
            if arg in self.deprecated_args:
                _warn(arg, 'CLI')

        for arg in answer_file_args:
            if arg in self.deprecated_args:
                _warn(arg, 'Answer file')

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not hasattr(self, 'parser'):
        raise AttributeError("Parser not initialized")
    return self.parser.get_option_specs(command_name)

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    for name, value in args.items():
        if value is None or value is False:
            silent.append(name)
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    missing = [arg for arg in self.REQUIRED_ARGS if arg not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        if 'required_when' not in opt:
            continue
        cond = opt['required_when']
        try:
            if callable(cond):
                if cond(args):
                    required.append(opt['name'])
            else:
                # Assume a string expression that can be evaluated with args as locals
                if eval(cond, {}, args):
                    required.append(opt['name'])
        except Exception:
            # If the condition cannot be evaluated, ignore it
            pass
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for key, value in args.items():
        max_len = getattr(self, f"{key}_max_length", None)
        if max_len is None:
            max_len = getattr(self, "max_lengths", {}).get(key)
        if max_len is not None and isinstance(value, (str, list, tuple, dict)):
            if len(value) > max_len:
                raise ValueError(f"Argument '{key}' length {len(value)} exceeds maximum of {max_len}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Assume self.choices is a mapping of argument names to a list/tuple of allowed values.
    for key, value in args.items():
        if key in getattr(self, "choices", {}):
            allowed = self.choices[key]
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value!r}. "
                    f"Expected one of {allowed!r}."
                )
    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    for key, value in args.items():
        min_attr = f"{key}_min"
        max_attr = f"{key}_max"

        if hasattr(self, min_attr) and hasattr(self, max_attr):
            min_val = getattr(self, min_attr)
            max_val = getattr(self, max_attr)

            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument '{key}' with value {value} is out of bounds "
                    f"[{min_val}, {max_val}]"
                )

    return True

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Accept either a dict or an iterable of (key, value) pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        items = args

    for key, value in items:
        # Treat keys starting with '_' or 'control_' as control arguments
        if isinstance(key, str) and (key.startswith('_') or key.startswith('control_')):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict

        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
        else:
            for item in extra_vars:
                if isinstance(item, dict):
                    vars_dict.update(item)
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                else:
                    raise TypeError(
                        "extra_vars must be a dict or a list/tuple of key-value pairs"
                    )
        return vars_dict

cmd = ['ansible-playbook', playbook_path]
    if verbose:
        # Add verbosity flags (e.g., -v, -vv, -vvv)
        cmd.extend(['-v'] * verbose)
    if extra_vars:
        # Pass extra variables as JSON string
        cmd.extend(['--extra-vars', json.dumps(extra_vars)])
    if ansible_args:
        for key, value in ansible_args.items():
            flag = f'--{key}'
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            else:
                cmd.extend([flag, str(value)])
    # Determine working directory (use workspace path if available)
    cwd = getattr(ir_workspace, 'path', None) or os.getcwd()
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
            check=True
        )
        if verbose:
            print(result.stdout)
        return result
    except subprocess.CalledProcessError as exc:
        if verbose:
            print(exc.stdout)
            print(exc.stderr)
        raise

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Attempt to cast values based on known types for this parser
    # If a type mapping is defined on the instance, use it
    type_map = getattr(self, 'parser_type_map', {}).get(parser_name, {})
    for key, val in list(values_dict.items()):
        # Skip if value is already not a string
        if not isinstance(val, str):
            continue
        # Determine target type
        target_type = type_map.get(key)
        if target_type is None:
            # Heuristic: try int, float, bool
            lowered = val.lower()
            if lowered in ('true', 'false', 'yes', 'no', 'on', 'off'):
                target_type = bool
            else:
                try:
                    int(val)
                    target_type = int
                except ValueError:
                    try:
                        float(val)
                        target_type = float
                    except ValueError:
                        target_type = str
        # Perform conversion
        try:
            if target_type is bool:
                values_dict[key] = val.lower() in ('true', '1', 'yes', 'on')
            else:
                values_dict[key] = target_type(val)
        except Exception:
            # If conversion fails, keep original string
            values_dict[key] = val

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_path):
        raise FileNotFoundError(f"Plugin spec file not found: {spec_path}")
    with open(spec_path, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    def _flatten(d, parent_key=''):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        default_path = os.path.join(os.path.dirname(__file__), 'config.json')
        os.environ['CONFIG_PATH'] = default_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        return path
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    if len(path) > len(root) and path[len(root)] not in ('/', '\\'):
        raise ValueError(f"Path '{path}' does not start with root '{root}' as a directory component.")
    new_path = path[len(root):]
    new_path = new_path.lstrip('/\\')
    return new_path
